#[test]
fn branch_meta_matches_the_upstream_index() {
    let reader = open_fixture();
    let meta = reader.branch_meta(SESSION_ID).expect("branch_meta");
    assert_eq!(
        meta,
        vec![
            BranchMeta {
                branch_id: "e1-user".into(),
                tip_entry_id: "e6-branch-summary".into(),
                tip_seq: 6,
                base_branch_id: None,
                base_seq: None,
            },
            BranchMeta {
                branch_id: "e7-fork".into(),
                tip_entry_id: "e7-fork".into(),
                tip_seq: 10,
                base_branch_id: Some("e1-user".into()),
                base_seq: Some(4),
            },
        ]
    );

    assert_eq!(
        reader
            .branch_meta_for(SESSION_ID, "e7-fork")
            .expect("branch_meta_for"),
        Some(meta[1].clone())
    );
    assert_eq!(
        reader
            .branch_meta_for(SESSION_ID, "nope")
            .expect("branch_meta_for"),
        None
    );
}

#[test]
fn branch_entries_keep_the_copied_tail_per_branch() {
    let reader = open_fixture();

    let root = reader
        .branch_entries(SESSION_ID, "e1-user")
        .expect("branch_entries");
    assert_eq!(
        root,
        vec![
            BranchEntry {
                branch_id: "e1-user".into(),
                entry_id: "e1-user".into(),
                entry_seq: 1,
                entry_type: "message".into(),
            },
            BranchEntry {
                branch_id: "e1-user".into(),
                entry_id: "e2-assistant".into(),
                entry_seq: 2,
                entry_type: "message".into(),
            },
            BranchEntry {
                branch_id: "e1-user".into(),
                entry_id: "e3-toolresult".into(),
                entry_seq: 3,
                entry_type: "message".into(),
            },
            BranchEntry {
                branch_id: "e1-user".into(),
                entry_id: "e4-compaction".into(),
                entry_seq: 4,
                entry_type: "compaction".into(),
            },
            BranchEntry {
                branch_id: "e1-user".into(),
                entry_id: "e5-custom".into(),
                entry_seq: 5,
                entry_type: "custom".into(),
            },
            BranchEntry {
                branch_id: "e1-user".into(),
                entry_id: "e6-branch-summary".into(),
                entry_seq: 6,
                entry_type: "branch_summary".into(),
            },
        ]
    );

    // The divergent branch re-owns the post-compaction tail (e5, e6) and
    // then extends it with the fork entry.
    let fork = reader
        .branch_entries(SESSION_ID, "e7-fork")
        .expect("branch_entries");
    assert_eq!(fork.len(), 3);
    assert_eq!(
        fork.iter().map(|row| &row.entry_id).collect::<Vec<_>>(),
        vec!["e5-custom", "e6-branch-summary", "e7-fork"]
    );
    assert_eq!(
        fork.iter().map(|row| row.entry_seq).collect::<Vec<_>>(),
        vec![5, 6, 10]
    );

    assert!(reader
        .branch_entries(SESSION_ID, "missing")
        .expect("branch_entries")
        .is_empty());
}

#[test]
fn branch_scan_walks_segments_in_both_directions() {
    let reader = open_fixture();

    let ids = |scan: &BranchScan| -> Vec<String> {
        reader
            .scan_branch(SESSION_ID, scan)
            .expect("scan_branch")
            .into_iter()
            .map(|entry| entry.entry_id.expect("upstream entries carry ids"))
            .collect()
    };

    // `start` is the anchor the walk ends at (upstream resolves the
    // branch membership from that entry), so starting at the root entry
    // yields just that entry.
    assert_eq!(ids(&BranchScan::from("e1-user")), vec!["e1-user"]);
    assert_eq!(
        ids(&BranchScan {
            order: BranchOrder::OldestFirst,
            ..BranchScan::from("e1-user")
        }),
        vec!["e1-user"]
    );

    // The fork has two segments: its own tail, then the base branch up to
    // the compaction boundary. `e5`/`e6` are only returned once — from the
    // fork segment, which is the newer one.
    assert_eq!(
        ids(&BranchScan {
            order: BranchOrder::OldestFirst,
            ..BranchScan::from("e7-fork")
        }),
        vec![
            "e1-user",
            "e2-assistant",
            "e3-toolresult",
            "e4-compaction",
            "e5-custom",
            "e6-branch-summary",
            "e7-fork",
        ]
    );
    assert_eq!(
        ids(&BranchScan::from("e7-fork")),
        vec![
            "e7-fork",
            "e6-branch-summary",
            "e5-custom",
            "e4-compaction",
            "e3-toolresult",
            "e2-assistant",
            "e1-user",
        ]
    );

    // `e6` belongs to both branches; the membership query picks the branch
    // with the newest tip (the fork), which is why the root branch's full
    // walk and the fork's walk agree once the mark is below the fork.
    assert_eq!(
        ids(&BranchScan {
            order: BranchOrder::OldestFirst,
            ..BranchScan::from("e6-branch-summary")
        }),
        vec![
            "e1-user",
            "e2-assistant",
            "e3-toolresult",
            "e4-compaction",
            "e5-custom",
            "e6-branch-summary",
        ]
    );

    // Scans decode; they do not hand back raw rows.
    let entries = reader
        .scan_branch(SESSION_ID, &BranchScan::from("e7-fork"))
        .expect("scan_branch");
    assert_eq!(entries[0].seq, 10);
    assert_eq!(entries[0].entry_id.as_deref(), Some("e7-fork"));
    assert_eq!(entries[0].type_, "message");
    assert!(matches!(
        entries[0].entry,
        pi_protocol::SessionEntry::UserMessage(_)
    ));
    assert_eq!(entries[3].type_, "compaction");
    assert!(matches!(
        entries[3].entry,
        pi_protocol::SessionEntry::Compaction { .. }
    ));

    // An entry that is not in the branch index is a corrupt index, and
    // upstream throws for it too.
    let err = reader
        .scan_branch(SESSION_ID, &BranchScan::from("no-such-entry"))
        .unwrap_err();
    assert!(
        err.to_string().contains("branch cache missing entry"),
        "unexpected error: {err}"
    );
}

#[test]
fn branch_scan_applies_type_cursor_limit_and_stop() {
    let reader = open_fixture();

    let ids = |scan: &BranchScan| -> Vec<String> {
        reader
            .scan_branch(SESSION_ID, scan)
            .expect("scan_branch")
            .into_iter()
            .map(|entry| entry.entry_id.expect("upstream entries carry ids"))
            .collect()
    };

    // Limit stops the walk once the budget is spent (oldest first, so the
    // oldest entries win).
    assert_eq!(
        ids(&BranchScan {
            order: BranchOrder::OldestFirst,
            limit: Some(3),
            ..BranchScan::from("e7-fork")
        }),
        vec!["e1-user", "e2-assistant", "e3-toolresult"]
    );
    assert!(ids(&BranchScan {
        limit: Some(0),
        ..BranchScan::from("e7-fork")
    })
    .is_empty());

    // `type_` filters on `branch_entries.entry_type`; only the fork branch
    // has a `custom` entry.
    assert_eq!(
        ids(&BranchScan {
            order: BranchOrder::OldestFirst,
            type_: Some("custom".into()),
            ..BranchScan::from("e7-fork")
        }),
        vec!["e5-custom"]
    );

    // `custom_type` filters on `entries.custom_type`.
    assert_eq!(
        ids(&BranchScan {
            order: BranchOrder::OldestFirst,
            custom_type: Some("ts-fixture:marker".into()),
            ..BranchScan::from("e7-fork")
        }),
        vec!["e5-custom"]
    );

    // `cursor` is exclusive and applied per segment (upstream resumes a
    // paged scan that way).
    assert_eq!(
        ids(&BranchScan {
            order: BranchOrder::OldestFirst,
            cursor: Some(3),
            ..BranchScan::from("e7-fork")
        }),
        vec!["e4-compaction", "e5-custom", "e6-branch-summary", "e7-fork",]
    );

    // `stop_at_type` is inclusive and cuts the walk at the newest matching
    // entry of the first segment that has one.
    assert_eq!(
        ids(&BranchScan {
            stop_at_type: Some("compaction".into()),
            ..BranchScan::from("e7-fork")
        }),
        vec!["e7-fork", "e6-branch-summary", "e5-custom", "e4-compaction",]
    );

    // `stop_at_id` behaves the same and, walking newest first, still
    // includes the entries between the tip and the stop entry.
    assert_eq!(
        ids(&BranchScan {
            stop_at_id: Some("e3-toolresult".into()),
            ..BranchScan::from("e7-fork")
        }),
        vec![
            "e7-fork",
            "e6-branch-summary",
            "e5-custom",
            "e4-compaction",
            "e3-toolresult",
        ]
    );
}

// ---------------------------------------------------------------------
// legacy layout
// ---------------------------------------------------------------------

#[test]
fn projection_reads_reject_the_rust_legacy_layout() {
    let dir: PathBuf = fresh_dir("usage-branch-legacy");
    let path = dir.join("legacy.sqlite");
    write_rust_legacy_fixture(&path, "legacy", "0.1.0", &[]);

    let reader = SessionReader::open(&path).expect("open legacy");
    assert_eq!(reader.layout(), SchemaLayout::RustLegacy);

    // The legacy layout has none of these tables; reading must fail loudly
    // instead of looking like an empty session.
    for err in [
        reader.iter_usage("legacy").unwrap_err(),
        reader.session_stats("legacy").unwrap_err(),
        reader.recompute_stats("legacy").unwrap_err(),
        reader.branch_meta("legacy").unwrap_err(),
        reader
            .scan_branch("legacy", &BranchScan::from("x"))
            .unwrap_err(),
    ] {
        assert!(
            matches!(err, pi_session::SessionError::Other(_)),
            "expected a layout error, got {err:?}"
        );
        assert!(
            err.to_string().contains("upstream v4 layout"),
            "unexpected error: {err}"
        );
    }
}

/// The fixture path helper must not silently accept a missing file.
#[test]
fn the_fixture_exists() {
    assert!(Path::new(&fixture_path()).exists());
}
